#!/usr/bin/env bash
set -euo pipefail

repo="${1:-/Users/feniix/src/personal/pi/pi-extensions}"
extension="$repo/packages/pi-statusline/extensions/index.ts"
start_at="${SMOKE_START_AT:-1}"
case "$start_at" in
  1|2|3|4) ;;
  *) printf 'SMOKE_START_AT must be 1, 2, 3, or 4.\n' >&2; exit 1 ;;
esac

if [[ ! -t 0 || ! -t 1 ]]; then
  printf 'Run this script directly in an interactive terminal.\n' >&2
  exit 1
fi
if ! command -v pi >/dev/null 2>&1; then
  printf 'pi is not on PATH.\n' >&2
  exit 1
fi
if [[ ! -f "$extension" ]]; then
  printf 'Statusline not found: %s\nUsage: bash %s /path/to/pi-extensions\n' "$extension" "$0" >&2
  exit 1
fi
repo="$(cd "$repo" && pwd -P)"
extension="$repo/packages/pi-statusline/extensions/index.ts"

version="$(pi --version)"
case "$version" in
  1.*) ;;
  *) printf 'Expected pi 1.x; found %s.\n' "$version" >&2; exit 1 ;;
esac

scratch="$(mktemp -d "${TMPDIR:-/tmp}/pi-statusline-smoke.XXXXXX")"
trap 'rm -rf -- "$scratch"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
helper="$scratch/helper.ts"
report="$(mktemp "${TMPDIR:-/tmp}/pi-statusline-report.XXXXXX")"

cat > "$helper" <<'EOF'
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
  pi.registerCommand("smoke", {
    description: "Show Unicode extension statuses and a user prompt",
    handler: async (_args, ctx) => {
      ctx.ui.setStatus("smoke-a", "🧪 项目 e\u0301 — smoke test");
      ctx.ui.setStatus("smoke-b", "Second extension status");
      await ctx.ui.confirm("Smoke test", "Inspect the footer, then choose either answer.");
    },
  });
  pi.registerCommand("smoke-clear", {
    description: "Remove smoke-test extension statuses",
    handler: async (_args, ctx) => {
      ctx.ui.setStatus("smoke-a", undefined);
      ctx.ui.setStatus("smoke-b", undefined);
    },
  });
  pi.registerCommand("smoke-help", {
    description: "Show the manual smoke-test checklist",
    handler: async (_args, ctx) => {
      ctx.ui.notify(
        "Resize to 40/80/120 columns; /smoke; dismiss; /smoke-clear; /thinking. " +
        "Optional model prompt: Run sleep 3 using bash, then explain what you did. " +
        "Check exactly two footer lines, readable colors, waiting/tool/idle states and stable totals. " +
        "Exit pi with Ctrl+C twice while idle.",
        "info",
      );
    },
  });
}
EOF

{
  printf '# Statusline terminal smoke test\n\n'
  printf 'Date: %s\nPi: %s\nRepository: %s\n' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" "$version" "$repo"
  printf 'Extension: %s\n\n' "$extension"
} > "$report"

printf '\nStatusline smoke test — pi %s\n' "$version"
printf 'Report: %s\n' "$report"
printf 'Uses local source, disables other extensions, and does not save sessions.\n'
printf 'Does not edit settings or publish anything. Model prompts use your credentials and may cost money.\n'
printf 'Do not enter credentials or other secrets in the report notes.\n\n'
read -r -p 'Terminal app/version (for the report): ' terminal
printf 'Terminal: %s\n\n' "$terminal" >> "$report"

step=0
for combination in fullscreen:dark fullscreen:light regular:dark regular:light; do
  step=$((step + 1))
  if [[ "$step" -lt "$start_at" ]]; then
    continue
  fi
  mode="${combination%%:*}"
  theme="${combination#*:}"
  printf '\n[%s/4] %s mode / %s theme\n' "$step" "$mode" "$theme"
  printf '%s\n' \
    '  1. Resize to about 40, 80, and 120 columns: exactly two lines, no overflow/artifacts.' \
    '  2. Run /smoke: both statuses appear; activity becomes "waiting for user".' \
    '  3. Dismiss the dialog: previous activity returns. /smoke-clear removes both statuses.' \
    '  4. Change /thinking (if the model supports it): footer updates immediately.' \
    '  5. Optional: ask "Run sleep 3 using bash, then explain what you did."' \
    '     Watch responding/tool activity, then idle; totals should not drop or double.' \
    '  6. Check readable theme colors. At narrow widths, context/activity/statuses lead.' \
    '  Use /smoke-help to redisplay guidance; Ctrl+C twice while idle exits pi.'
  read -r -p 'Press Enter to launch (or Ctrl+C to stop): ' _

  code=0
  (
    cd "$repo"
    pi --no-extensions --no-session \
      -e "$extension" -e "$helper" \
      --tui-mode "$mode" --use-theme "$theme"
  ) || code=$?

  printf '\nPi exited with code %s.\n' "$code"
  while true; do
    read -r -p 'Visual result [pass/fail/skipped]: ' result
    case "$result" in
      pass|fail|skipped) break ;;
      *) printf 'Enter pass, fail, or skipped.\n' ;;
    esac
  done
  read -r -p 'Model/tool activity test [pass/fail/skipped]: ' activity
  read -r -p 'Notes (optional; include widths/glitches): ' notes
  {
    printf '## %s / %s\n\n' "$mode" "$theme"
    printf -- '- Visual result: %s\n- Model/tool activity: %s\n- Pi exit code: %s\n' "$result" "$activity" "$code"
    printf -- '- Notes: %s\n\n' "${notes:-none}"
  } >> "$report"
done

printf '\nDone. Helper extension will be removed automatically.\n'
printf 'Report saved to: %s\n' "$report"
printf 'Review it, then paste the results into https://github.com/feniix/pi-extensions/pull/148\n'

